import React from 'react';
import {
  Alert,
  Box,
  Chip,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import {
  ORCHESTRATOR_MSME_LABELS,
  buildStageOutcomeBullets,
  humanizeOrchestrationStage,
  EMPTY_READINESS_CHECK_PROMPT,
} from '../../constants/orchestrationUxLabels';

export type OrchestrationRunSummary = {
  orchestratorType?: string;
  lastRunAt?: string | Date;
  scoreBefore?: number | null;
  scoreAfter?: number | null;
  scoreDelta?: number | null;
  message?: string | null;
  stagesCompleted?: number;
  stagesFailed?: number;
  success?: boolean;
  stages?: Array<{ stage: string; status: string; durationMs?: number | null; error?: string | null }>;
};

export type OrchestrationStage = {
  stage: string;
  status: string;
  durationMs?: number | null;
  error?: string | null;
};

export const stagesFromRun = (lastRun?: OrchestrationRunSummary | null): OrchestrationStage[] => {
  const stages = lastRun?.stages;
  return Array.isArray(stages) ? stages : [];
};

type OrchestrationRunPanelProps = {
  title?: string;
  lastRun?: OrchestrationRunSummary | null;
  stages?: Array<{ stage: string; status: string; durationMs?: number | null; error?: string | null }>;
  compact?: boolean;
  running?: boolean;
  runningStageLabel?: string;
  showEmptyPrompt?: boolean;
  emptyPrompt?: string;
};

const OrchestrationRunPanel: React.FC<OrchestrationRunPanelProps> = ({
  title = 'Readiness check',
  lastRun,
  stages = [],
  compact = false,
  running = false,
  runningStageLabel,
  showEmptyPrompt = false,
  emptyPrompt = EMPTY_READINESS_CHECK_PROMPT,
}) => {
  if (running) {
    return (
      <Alert severity="info" sx={{ mb: 2 }}>
        <Typography variant="subtitle2" gutterBottom>
          {runningStageLabel || 'Running readiness check…'}
        </Typography>
        <LinearProgress sx={{ mt: 1, mb: 1 }} />
        <Typography variant="caption" color="text.secondary">
          This usually takes about a minute. You can stay on this page.
        </Typography>
      </Alert>
    );
  }

  if (!lastRun && !stages.length) {
    if (!showEmptyPrompt) {
      return null;
    }
    return (
      <Alert severity="info" sx={{ mb: 2 }}>
        <Typography variant="body2">{emptyPrompt}</Typography>
      </Alert>
    );
  }

  const label = ORCHESTRATOR_MSME_LABELS[lastRun?.orchestratorType || ''] || title;
  const runAt = lastRun?.lastRunAt ? new Date(lastRun.lastRunAt).toLocaleString() : null;
  const outcomeBullets = buildStageOutcomeBullets(stages.length ? stages : lastRun?.stages || []);
  const displayStages = stages.length ? stages : lastRun?.stages || [];

  return (
    <Alert severity={lastRun?.success === false ? 'warning' : 'success'} sx={{ mb: 2 }}>
      <Typography variant="subtitle2" gutterBottom>
        {label}
        {runAt ? ` · Last checked ${runAt}` : ''}
      </Typography>
      {lastRun?.message ? (
        <Typography variant="body2" sx={{ mb: 1 }}>
          {lastRun.message.replace(/orchestration/gi, 'readiness check')}
        </Typography>
      ) : null}
      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: outcomeBullets.length ? 1 : 0 }}>
        {lastRun?.scoreAfter != null ? (
          <Chip size="small" label={`Readiness ${Math.round(lastRun.scoreAfter)}%`} color="primary" variant="outlined" />
        ) : null}
        {lastRun?.scoreDelta != null && lastRun.scoreDelta !== 0 ? (
          <Chip
            size="small"
            label={`${lastRun.scoreDelta > 0 ? '+' : ''}${Math.round(lastRun.scoreDelta)}% since last check`}
            color={lastRun.scoreDelta > 0 ? 'success' : 'default'}
            variant="outlined"
          />
        ) : null}
        {lastRun?.stagesFailed ? (
          <Chip size="small" label={`${lastRun.stagesFailed} step(s) need review`} color="warning" variant="outlined" />
        ) : null}
      </Stack>
      {!compact && outcomeBullets.length ? (
        <Box sx={{ mt: 1 }}>
          <Typography variant="caption" color="text.secondary" fontWeight={600} display="block" sx={{ mb: 0.5 }}>
            What we checked
          </Typography>
          {outcomeBullets.map((bullet) => (
            <Typography key={bullet} variant="body2" color="text.secondary" display="block">
              ✓ {bullet}
            </Typography>
          ))}
        </Box>
      ) : null}
      {!compact && displayStages.length ? (
        <Box sx={{ mt: 1.5 }}>
          <Typography variant="caption" color="text.secondary" fontWeight={600} display="block" sx={{ mb: 0.5 }}>
            Step detail
          </Typography>
          {displayStages.map((stage) => (
            <Typography key={stage.stage} variant="caption" color="text.secondary" display="block">
              {stage.status === 'completed' ? '✓' : stage.status === 'skipped' ? '–' : '✗'}{' '}
              {humanizeOrchestrationStage(stage.stage)}
            </Typography>
          ))}
        </Box>
      ) : null}
    </Alert>
  );
};

export default OrchestrationRunPanel;
