import React, { useMemo, useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Button,
  Chip,
  Stack,
  Typography,
} from '@mui/material';
import {
  ExpandMore as ExpandMoreIcon,
  RadioButtonUnchecked as OpenIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { estimatedScoreImpactForRemediation } from '../../constants/reportingUxLabels';

import {
  MSME_SIMPLIFIED_GAP_SUBTITLE,
  MSME_SIMPLIFIED_GAP_TITLE,
  msmeSimplifiedActionLabel,
} from '../../constants/msmeSimplifiedUi';

export type ReadinessGapItem = {
  id: string;
  label: string;
  detail?: string | null;
  hubLink?: string | null;
  category?: string;
  dataFeedSatisfied?: boolean;
};

export type ModuleGapBundle = {
  moduleKey: string;
  label: string;
  score?: number | null;
  threshold?: number | null;
  hubLink?: string;
  gapCount: number;
  gaps: ReadinessGapItem[];
};

type ComplianceReadinessGapPanelProps = {
  moduleGapDetails: Record<string, ModuleGapBundle>;
  moduleKeys: string[];
  title?: string;
  simplified?: boolean;
  period?: string;
  onResolved?: () => void;
  /** Overview-only presentation. Other pages keep the previous text actions. */
  overviewPresentation?: boolean;
  /** Outlined Add data / Review data actions and row-specific accessible names. */
  emphasizeRowActions?: boolean;
};

const overviewDataButtonSx = {
  flexShrink: 0,
  alignSelf: 'flex-start',
  maxWidth: '100%',
  '&:hover': {
    borderColor: 'primary.main',
    bgcolor: 'background.paper',
  },
};

const ComplianceReadinessGapPanel: React.FC<ComplianceReadinessGapPanelProps> = ({
  moduleGapDetails,
  moduleKeys,
  title = 'Details required to raise readiness scores',
  simplified = false,
  overviewPresentation = false,
  emphasizeRowActions = false,
}) => {
  const [expanded, setExpanded] = useState<string | false>(false);

  const modulesWithGaps = useMemo(
    () => moduleKeys
      .map((key) => moduleGapDetails[key])
      .filter((bundle): bundle is ModuleGapBundle => Boolean(bundle && bundle.gapCount > 0)),
    [moduleGapDetails, moduleKeys]
  );

  const panelTitle = simplified ? MSME_SIMPLIFIED_GAP_TITLE : title;

  if (!modulesWithGaps.length) {
    return (
      <Box sx={{ mb: 3 }}>
        <Typography variant="subtitle1" fontWeight={700} sx={{ mb: 1 }}>
          {panelTitle}
        </Typography>
        <Typography variant="body2" color="text.secondary">
          No open data gaps detected for these modules — scores are on track for the current period.
        </Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ mb: 3 }}>
      <Typography variant="subtitle1" fontWeight={700} sx={{ mb: 0.5 }}>
        {panelTitle}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {simplified
          ? MSME_SIMPLIFIED_GAP_SUBTITLE
          : 'Complete the items below to increase each report\'s readiness score. Each gap links to where you can add the required data.'}
      </Typography>

      {modulesWithGaps.map((bundle) => (
        <Accordion
          key={bundle.moduleKey}
          expanded={expanded === bundle.moduleKey}
          onChange={(_, isExpanded) => setExpanded(isExpanded ? bundle.moduleKey : false)}
          variant="outlined"
          sx={{ mb: 1, '&:before': { display: 'none' } }}
        >
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" sx={{ width: '100%', pr: 1 }}>
              <Typography fontWeight={600}>{bundle.label}</Typography>
              {bundle.score != null ? (
                <Chip size="small" label={`${Math.round(bundle.score)}%`} />
              ) : null}
              <Chip size="small" color="warning" label={`${bundle.gapCount} gap${bundle.gapCount === 1 ? '' : 's'}`} />
              {bundle.threshold != null && bundle.score != null && bundle.score < bundle.threshold ? (
                <Chip size="small" variant="outlined" label={`Target ${bundle.threshold}%`} />
              ) : null}
            </Stack>
          </AccordionSummary>
          <AccordionDetails>
            <Stack spacing={1.5}>
              {bundle.gaps.map((gap) => {
                const scoreImpact = estimatedScoreImpactForRemediation(gap.label);
                const gapTitle = msmeSimplifiedActionLabel(gap.label, gap.dataFeedSatisfied);
                const dataActionLabel = gap.dataFeedSatisfied ? 'Review data' : 'Add data';
                const detailText = typeof gap.detail === 'string' ? gap.detail.trim() : '';
                const showDetail = detailText.length > 0 && detailText !== gapTitle.trim();
                const emphasizeDataAction = overviewPresentation || emphasizeRowActions;
                return (
                <Box
                  key={gap.id}
                  sx={{
                    display: 'flex',
                    flexWrap: 'wrap',
                    alignItems: 'flex-start',
                    justifyContent: 'space-between',
                    gap: 1,
                    p: 1.25,
                    borderRadius: 1,
                    bgcolor: 'action.hover',
                  }}
                >
                  <Stack direction="row" spacing={1} alignItems="flex-start" sx={{ flex: 1, minWidth: 220 }}>
                    <OpenIcon fontSize="small" color="action" sx={{ mt: 0.3 }} />
                    <Box>
                      <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                        <Typography variant="body2" fontWeight={600}>
                          {gapTitle}
                        </Typography>
                        {scoreImpact ? (
                          <Chip size="small" label={`~+${Number(scoreImpact).toFixed(1)}%`} color="success" variant="outlined" />
                        ) : null}
                      </Stack>
                      {showDetail ? (
                        <Typography variant="body2" color="text.secondary">
                          {gap.detail}
                        </Typography>
                      ) : null}
                    </Box>
                  </Stack>
                  {gap.hubLink ? (
                    <Button
                      size="small"
                      variant={emphasizeDataAction ? 'outlined' : 'text'}
                      component={RouterLink}
                      to={gap.hubLink}
                      aria-label={emphasizeDataAction ? `${dataActionLabel}: ${gapTitle}` : undefined}
                      sx={emphasizeDataAction ? overviewDataButtonSx : { flexShrink: 0, alignSelf: 'flex-start', maxWidth: '100%' }}
                    >
                      {dataActionLabel}
                    </Button>
                  ) : null}
                </Box>
              );
              })}
              {bundle.hubLink ? (
                <Button size="small" component={RouterLink} to={bundle.hubLink} sx={{ alignSelf: 'flex-start' }}>
                  Open {bundle.label} section
                </Button>
              ) : null}
            </Stack>
          </AccordionDetails>
        </Accordion>
      ))}
    </Box>
  );
};

export default ComplianceReadinessGapPanel;
