import { useCallback, useRef, useState } from 'react';
import ApiService from '../services/api';
import type { OrchestrationRunSummary } from '../components/compliance/OrchestrationRunPanel';

export type OrchestrationStage = {
  stage: string;
  status: string;
  durationMs?: number | null;
  error?: string | null;
};

export type ComplianceOrchestrationResult = {
  message?: string;
  overallReadinessScore?: number;
  overallScoreDelta?: number | null;
  indiaOverallReadinessScore?: number;
  exportOverallReadinessScore?: number;
  exportApplicable?: boolean;
  stages?: OrchestrationStage[];
  orchestrationRun?: OrchestrationRunSummary;
  agentOutputs?: Record<string, unknown>;
  partialFailures?: Array<{ type?: string; id?: string; message?: string }>;
  hasPartialFailures?: boolean;
  success?: boolean;
};

type UseComplianceOrchestrationOptions = {
  period?: string;
  exportApplicable?: boolean;
  onComplete?: () => void;
};

export const useComplianceOrchestration = ({
  period = 'annual',
  exportApplicable = false,
  onComplete,
}: UseComplianceOrchestrationOptions = {}) => {
  const [running, setRunning] = useState(false);
  const [autopilotRunning, setAutopilotRunning] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [lastResult, setLastResult] = useState<ComplianceOrchestrationResult | null>(null);
  const [stages, setStages] = useState<OrchestrationStage[]>([]);
  const [partialFailures, setPartialFailures] = useState<
    Array<{ type?: string; id?: string; message?: string }>
  >([]);
  const [hasPartialFailures, setHasPartialFailures] = useState(false);
  const abortRef = useRef(false);

  const runFullReadinessCheck = useCallback(async () => {
    if (running) return null;
    abortRef.current = false;
    setRunning(true);
    setError(null);
    setFeedback(null);
    try {
      // Light readiness first (CI-BUG-013): avoid full framework autopilot that 504s the edge gateway.
      const res = await ApiService.orchestrateReportingReadiness({
        period,
        actionLimit: 8,
        runAutopilot: false,
        includeBrsrOrchestration: false,
        includeIsoOrchestration: false,
        includePcfOrchestration: false,
        includeCbamOrchestration: false,
        includeCertificationOrchestration: false,
        includeHeavyStages: false,
        includeInventoryReview: true,
        includeBuyerOrchestration: true,
      });
      if (abortRef.current) return null;
      const data = ((res as { data?: ComplianceOrchestrationResult })?.data || res) as ComplianceOrchestrationResult;
      const normalizedStages = (data.stages || []) as OrchestrationStage[];
      setStages(normalizedStages);
      setLastResult(data);
      const failures = Array.isArray(data.partialFailures) ? data.partialFailures : [];
      setPartialFailures(failures);
      setHasPartialFailures(Boolean(data.hasPartialFailures || failures.length > 0));
      const scoreParts = [
        data.overallReadinessScore != null ? `Overall ${Math.round(data.overallReadinessScore)}%` : null,
        data.overallScoreDelta != null && data.overallScoreDelta !== 0
          ? `${data.overallScoreDelta > 0 ? '+' : ''}${Math.round(data.overallScoreDelta)}%`
          : null,
      ].filter(Boolean);
      setFeedback(
        failures.length > 0
          ? (data.message?.replace(/orchestration/gi, 'readiness check')
            || `Readiness check finished with ${failures.length} agent step(s) incomplete — retry if a step looks stuck.`)
          : (data.message?.replace(/orchestration/gi, 'readiness check')
            || (scoreParts.length
              ? `Readiness check complete: ${scoreParts.join(' · ')}.`
              : 'Readiness check complete — see what to fix next below.'))
      );
      onComplete?.();
      return data;
    } catch (e) {
      if (!abortRef.current) {
        setError(e instanceof Error ? e.message : 'Readiness check failed. Please try again.');
        onComplete?.();
      }
      return null;
    } finally {
      if (!abortRef.current) {
        setRunning(false);
      }
    }
  }, [exportApplicable, onComplete, period, running]);

  const runAutopilot = useCallback(async () => {
    if (autopilotRunning) return null;
    setAutopilotRunning(true);
    setError(null);
    setFeedback(null);
    try {
      const result = await ApiService.runComplianceHubAutopilot({
        period,
        applyChanges: true,
        runAgents: true,
      });
      const payload = (result as { data?: { closuresApplied?: unknown[]; documentVerifications?: unknown[] } })?.data;
      const closuresApplied = payload?.closuresApplied;
      const documentVerifications = payload?.documentVerifications;
      const closureCount = Array.isArray(closuresApplied) ? closuresApplied.length : 0;
      const docCount = Array.isArray(documentVerifications) ? documentVerifications.length : 0;
      setFeedback(
        closureCount || docCount
          ? `Auto-fix complete — ${docCount} bill check(s), ${closureCount} update(s) applied.`
          : 'Auto-fix finished — no additional changes were needed.'
      );
      onComplete?.();
      return result;
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Auto-fix from documents failed');
      return null;
    } finally {
      setAutopilotRunning(false);
    }
  }, [autopilotRunning, onComplete, period]);

  const reset = useCallback(() => {
    abortRef.current = true;
    setRunning(false);
    setAutopilotRunning(false);
    setFeedback(null);
    setError(null);
    setPartialFailures([]);
    setHasPartialFailures(false);
  }, []);

  return {
    running,
    autopilotRunning,
    feedback,
    error,
    lastResult,
    stages,
    partialFailures,
    hasPartialFailures,
    runFullReadinessCheck,
    runAutopilot,
    reset,
    setFeedback,
    setError,
  };
};

export default useComplianceOrchestration;
